package rs.unicredit.cbr.mq;

import java.nio.charset.StandardCharsets;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.CommandLineRunner;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.core.io.Resource;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.StreamUtils;

import lombok.RequiredArgsConstructor;
import rs.unicredit.cbr.model.CbrTransactionRequest;
import rs.unicredit.cbr.model.ParseStatus;
import rs.unicredit.cbr.repository.CbrTransactionRequestRepository;
import rs.unicredit.cbr.service.Pacs004ParserService;
import rs.unicredit.cbr.service.Pacs008ParserService;

/**
 * Simple loader that inserts a mock MQ payload into TBL_CBR_TRANSACTION_REQUEST.
 * Enabled only when mock.mq.enabled=true (intended for local/dev).
 */
@Component
@RequiredArgsConstructor
@ConditionalOnProperty(prefix = "mock.mq", name = "enabled", havingValue = "true")
public class MockMqLoader implements CommandLineRunner {

    private static final Logger LOG = LoggerFactory.getLogger(MockMqLoader.class);

    private final CbrTransactionRequestRepository requestRepository;
    private final Pacs008ParserService parserService;
    private final Pacs004ParserService pacs004ParserService;

    @Value("${mock.mq.resource:classpath:MQ_MESSAGE/pacs.008.001.08.om.001.xsd.xml}")
    private Resource mockMessage;

    @Value("${mock.mq.resources:}")
    private Resource[] mockMessages;

    @Value("${mock.mq.source-system:MQ_MOCK}")
    private String sourceSystem;

    @Override
    @Transactional
    public void run(String... args) throws Exception {
        Resource[] resources = resolveResources();
        if (resources.length == 0) {
            LOG.warn("No mock MQ payloads configured.");
            return;
        }
        for (Resource resource : resources) {
            if (resource == null || !resource.exists()) {
                LOG.warn("Mock MQ payload not found at {}", resource);
                continue;
            }
            String xml = StreamUtils.copyToString(resource.getInputStream(), StandardCharsets.UTF_8);
            CbrTransactionRequest request = new CbrTransactionRequest();
            request.setSourceSystem(sourceSystem);
            request.setRawXml(xml);
            request.setParseStatus(ParseStatus.RECEIVED);

            request = requestRepository.save(request);
            LOG.info("Inserted mock MQ message {} into TBL_CBR_TRANSACTION_REQUEST with id={}, parsing to transaction...",
                    resource.getFilename(), request.getId());

            if (isPacs004(xml)) {
                pacs004ParserService.parseAndSave(request);
            } else {
                parserService.parseAndSave(request);
            }
        }
    }

    private boolean isPacs004(String xml) {
        return xml != null && xml.contains("pacs.004");
    }

    private Resource[] resolveResources() {
        if (mockMessages != null && mockMessages.length > 0) {
            return mockMessages;
        }
        if (mockMessage != null) {
            return new Resource[] { mockMessage };
        }
        return new Resource[0];
    }
}

